export function validateSENSORYEYERIGHTSeed(): void {
  const slugs = new Set(
    SENSORY_EYE_RIGHT_STRUCTURES.map((structure) => structure.slug),
  );
  if (slugs.size !== SENSORY_EYE_RIGHT_STRUCTURES.length) {
    throw new Error(
      'Sensory system - right eye seed contains duplicate structure slugs.',
    );
  }
  const meshNames = new Set(
    SENSORY_EYE_RIGHT_STRUCTURES.map((structure) => structure.meshName),
  );
  if (meshNames.size !== SENSORY_EYE_RIGHT_STRUCTURES.length) {
    throw new Error(
      'Sensory system - right eye seed contains duplicate mesh names.',
    );
  }
  if (SENSORY_EYE_RIGHT_STRUCTURES.length !== 21) {
    throw new Error(
      'Sensory system - right eye seed must contain exactly 21 structures.',
    );
  }
  for (const structure of SENSORY_EYE_RIGHT_STRUCTURES) {
    for (const relatedSlug of structure.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(
          `Structure "${structure.slug}" references unknown related slug "${relatedSlug}".`,
        );
      }
    }
    if (structure.references.length === 0) {
      throw new Error(`Structure "${structure.slug}" has no references.`);
    }
    if (
      structure.meshName !== null &&
      !/^[a-z0-9_]+$/.test(structure.meshName)
    ) {
      throw new Error(
        `Structure "${structure.slug}" has an invalid mesh name "${structure.meshName}".`,
      );
    }
  }
}
